This binary search never finishes on some inputs. Find the bug, fix it, and use the fixed version to find the index of 37 in [2, 5, 8, 12, 16, 23, 37, 41, 56, 72, 91].

def search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid
        else:
            hi = mid - 1
    return -1

